INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma duodenopancreatectomia (Cirurgia de Whipple), o dreno abdominal apresenta saída de líquido citrino no 3º DPO. A dosagem de amilase no líquido do dreno é maior que 3 vezes o limite superior da normalidade sérica. O paciente está afebril e estável. De acordo com o ISGPS (International Study Group on Pancreatic Surgery), esta condição é classificada como:", "options": {"a": "Fístula Pancreática Grau B.", "b": "Fístula Pancreática Grau C.", "c": "Fístula Pancreática Bioquímica (antigamente Grau A).", "d": "Abscesso peripancreático.", "e": "Drenagem normal de pâncreas."}, "answer": "c", "rationale": "A fístula bioquímica é apenas laboratorial, sem impacto na conduta clínica ou tempo de internação, não sendo considerada uma fístula com relevância clínica mas sim um vazamento bioquímico.", "option_rationales": {"a": "Incorreta. Exige mudança de conduta ou internação prolongada.", "b": "Incorreta. Exige reoperação ou causa falência orgânica.", "c": "Correta. Classificação atualizada para vazamentos subclínicos.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula Pancreática", "Whipple"]}', 221, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a conduta recomendada para uma fístula biliar de baixo débito (< 200 ml/dia) no 5º DPO de uma colecistectomia eletiva em que o paciente está assintomático e sem sinais de peritonite?", "options": {"a": "Laparotomia imediata.", "b": "Tratamento conservador (observação e manutenção da drenagem) pois a maioria fecha espontaneamente.", "c": "Realizar CPRE de urgência no mesmo dia.", "d": "Iniciar quimioterapia biliar.", "e": "Retirar o dreno imediatamente."}, "answer": "b", "rationale": "Fístulas de baixo débito em pacientes estáveis costumam ser originadas de pequenos ductos acessórios (Ducto de Luschka) e fecham sozinhas se houver drenagem adequada.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Conduta expectante vigilante.", "c": "Incorreta. Indicada se houver suspeita de coledocolitíase residual ou obstrução distal.", "d": "Incorreta.", "e": "Incorreta. Se retirar o dreno, a bile acumula e gera peritonite."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula Biliar", "Manejo"]}', 222, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''icterícia obstrutiva precoce'' (até o 3º DPO) após o transplante de fígado deve levantar a suspeita diagnóstica prioritária de:", "options": {"a": "Rejeição crônica.", "b": "Trombose de artéria hepática ou estenose da anastomose biliar.", "c": "Hepatite B recorrente.", "d": "Nutrição parenteral excessiva.", "e": "Cálculo de vesícula residual."}, "answer": "b", "rationale": "Complicações vasculares (trombose de artéria) causam isquemia biliar imediata, pois os ductos do enxerto dependem exclusivamente da artéria hepática para nutrição.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Urgência no transplante hepático.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Transplante", "Pós-operatório", "Fígado", "Icterícia"]}', 223, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente que utiliza inibidores seletivos da recaptação de serotonina (ISRS) para depressão é submetido a cirurgia abdominal e recebe doses generosas de Meperidina (Tramadul no pós-operatório). Ele desenvolve agitação, hipertermia, tremores, hipe-rreflexia e clonus. Qual a síndrome provável?", "options": {"a": "Hipertermia Maligna.", "b": "Sindrome Serotoninérgica.", "c": "Sindrome Neuroléptica Maligna.", "d": "Abstinência de opioides.", "e": "Crise de ansiedade aguda."}, "answer": "b", "rationale": "A interação de ISRS com certas medicações analgésicas (como a meperidina ou tramadol) pode precipitar um excesso de serotonina, caracterizado pela tríade de alterações autonômicas, neuromusculares e mentais.", "option_rationales": {"a": "Incorreta. Não apresenta hiperreflexia/clonus tipicamente (é rigidez ''em cano de chumbo'').", "b": "Correta. Iatrogenia medicamentosa perioperatória.", "c": "Incorreta. Associada a antipsicóticos.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Farmacologia", "Pós-operatório", "Serotonina", "Interação"]}', 224, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal medida de prevenção da ''lesão por pressão'' (escaras) em pacientes cirúrgicos imobilizados no leito por longo período é:", "options": {"a": "Uso de massagem vigorosa nas proeminências ósseas.", "b": "Mudança sistemática de decúbito a cada 2 horas.", "c": "Uso de álcool 70% na pele.", "d": "Apenas colocar travesseiros macios.", "e": "Uso de antibióticos tópicos."}, "answer": "b", "rationale": "A redistribuição da pressão é a única forma eficaz de evitar a isquemia tecidual sobre proeminências ósseas como sacro e calcâneos.", "option_rationales": {"a": "Incorreta. Massagem pode aumentar o dano tecidual se já houver isquemia.", "b": "Correta. Pilar do cuidado de enfermagem e prevenção de complicações.", "c": "Incorreta. Resseca a pele e facilita lesão.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Enfermagem", "Pós-operatório", "Lesão por Pressão", "Prevenção"]}', 225, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual o achado laboratorial mais característico da Síndrome Neuroléptica Maligna, que ajuda a diferenciá-la de outras causas de hipertermia no pós-operatório?", "options": {"a": "Queda da creatinina.", "b": "Elevação marcante da Creatinofosfoquinase (CPK).", "c": "Aumento do tempo de protrombina.", "d": "Hipoglicemia.", "e": "Proteínas baixas no liquor."}, "answer": "b", "rationale": "A SNM cursa com intensa rigidez muscular (em cano de chumbo), o que leva a dano muscular e liberação massiva de CPK na corrente sanguínea.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Marcador de rabdomiólise associado à síndrome.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Psiquiatria", "Pós-operatório", "Síndrome Neuroléptica Maligna", "CPK"]}', 226, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma herniorrafia inguinal, o paciente apresenta dor tipo ''queimação'' e formigamento persistente que irradia para a bolsa escrotal ou grandes lábios. O cirurgião suspeita de aprisionamento nervoso pelo fio de sutura ou pela tela. Qual o nervo mais provável?", "options": {"a": "Nervo Femoral.", "b": "Nervo Ilioinguinal ou ramo genital do Genitofemoral.", "c": "Nervo Obturador.", "d": "Nervo Isquiático.", "e": "Nervo Sural."}, "answer": "b", "rationale": "A nevralgia pós-herniorrafia é uma complicação crônica comum. Os nervos ilioinguinal, ilio-hipogástrico e genitofemoral atravessam a região inguinal e podem ser lesionados ou comprimidos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Nervos sensitivos da região inguinal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Hérnia Inguinal", "Nevralgia"]}', 227, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia bariátrica (Sleeve Gástrico) apresenta dor abdominal súbita e taquicardia persistente (> 120 bpm) no 1º DPO. O paciente está afebril. Qual a complicação que deve ser investigada PRIORITARIAMENTE pelo risco de peritonite e sepse rápida?", "options": {"a": "Hipotireoidismo reacional.", "b": "Deiscência da linha de grampeamento gástrico (Fístula precoce).", "c": "Infecção urinária.", "d": "Pneumonia basal esquerda.", "e": "Dumping precoce."}, "answer": "b", "rationale": "A taquicardia persistente no pós-operatório bariátrico é o sinal clínico precoce mais sensível para deiscência de anastomose ou linha de grampeamento gástrico.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Sinal de alerta cardinal na cirurgia bariátrica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta. Dumping não costuma ser grave no 1º DPO se o paciente ainda estiver em dieta hídrica restrita."}, "difficulty": "media", "tags": ["Cirurgia Bariátrica", "Pós-operatório", "Deiscência", "Taquicardia"]}', 228, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em cirurgias de cabeça e pescoço, a manipulação do seio carotídeo pode desencadear qual complicação autonômica transoperatória ou no pós-operatório imediato?", "options": {"a": "Taquicardia supraventricular.", "b": "Bradicardia intensa ou assistolia por reflexo vagal.", "c": "Crise hipertensiva maligna.", "d": "Edema agudo de pulmão.", "e": "Hiperglicemia."}, "answer": "b", "rationale": "A pressão sobre o seio carotídeo estimula barorreceptores que enviam sinais ao tronco cerebral, resultando em aumento do tônus vagal e bradicardia reflexa.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Reflexo barorreceptor clássico.", "c": "Incorreta. Geralmente causa hipotensão.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Reflexo Carotídeo", "Bradicardia"]}', 229, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação do uso excessivo de ''soro fisiológico (NaCl 0.9%)'' durante a ressuscitação volêmica em grandes cirurgias abdominais?", "options": {"a": "Alcalose metabólica.", "b": "Acidose metabólica hiperclorêmica.", "c": "Hipernatremia extrema.", "d": "Cirrose hepática aguda.", "e": "Hipotensão refratária."}, "answer": "b", "rationale": "O soro fisiológico tem uma concentração de cloro (154 mEq/L) muito superior à do plasma (aprox. 100 mEq/L), o que leva ao deslocamento de bicarbonato e acidose hiperclorêmica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Distúrbio clássico da sobrecarga salina.", "c": "Incorreta. Embora o sódio seja alto, a acidose ocorre pelo cloro.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Clínica Médica", "Pós-operatório", "Fluidoterapia", "Acidose"]}', 230, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia torácica, o paciente desenvolve quadro de agitação, dispneia e o Raio-x mostra um desvio de traqueia para o lado oposto ao pulmão operado, além de hipertimpanismo à percussão. Qual a conduta de emergência?", "options": {"a": "Solicitar tomografia de tórax eletiva.", "b": "Puncionar o tórax com agulha no 2º ou 5º espaço intercostal (descompressão imediata de pneumotórax hipertensivo).", "c": "Realizar traqueostomia.", "d": "Administrar broncodilatadores.", "e": "Aumentar a pressão da ventilação mecânica."}, "answer": "b", "rationale": "O quadro é de pneumotórax hipertensivo, uma emergência que exige descompressão imediata com agulha antes mesmo da drenagem em selo d''água.", "option_rationales": {"a": "Incorreta. O paciente morrerá antes do exame.", "b": "Correta. Salvatagem imediata.", "c": "Incorreta. A via aérea está desviada mas não obstruída intrinsecamente.", "d": "Incorreta.", "e": "Incorreta. Pioraria o pneumotórax se houver fístula aérea."}, "difficulty": "facil", "tags": ["Cirurgia Torácica", "Pós-operatório", "Pneumotórax", "Emergência"]}', 231, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação conhecida como ''Síndrome de Mendelson'' refere-se a:", "options": {"a": "Atelectasia obstrutiva persistente.", "b": "Pneumonia aspirativa química causada pela aspiração de conteúdo gástrico ácido durante a indução anestésica ou no pós-operatório.", "c": "Embolia por corpo estranho.", "d": "Paralisia do nervo frênico.", "e": "Flebite após medicação irritante."}, "answer": "b", "rationale": "A aspiração de ácido gástrico causa uma pneumonite química fulminante que pode evoluir para SDRA severa.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Epônimo clássico da pneumonite aspirativa.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "Aspiração", "Pneumonite"]}', 232, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a esplenectomia pós-trauma desenvolve, no 5º DPO, o ''Sinal de Kehr'', que consiste em dor referida no ombro esquerdo. Qual a causa provável deste sinal no pós-operatório?", "options": {"a": "IAM apical.", "b": "Irritação do diafragma por sangue ou coleção subfrênica esquerda.", "c": "Fratura de úmero esquecida.", "d": "Derrame pleural isolado.", "e": "Colecistite reacional."}, "answer": "b", "rationale": "O nervo frênico (C3-C5) inerva o diafragma e compartilha raízes nervosas que dão sensibilidade ao ombro. A irritação do diafragma é percebida como dor no ombro.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Semiologia de irritação diafragmática.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Esplenectomia", "Semiologia"]}', 233, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A medida farmacológica isolada mais eficaz para prevenir a ocorrência de náuseas e vômitos pós-operatórios (NVPO) em pacientes de alto risco (mulheres, não fumantes, com história prévia de NVPO) é:", "options": {"a": "Uso de apenas ondansetrona isolada.", "b": "Abordagem multimodal combinando dexametasona na indução e antagonistas 5-HT3 (Ondansetrona) no final da cirurgia.", "c": "Uso de dipirona.", "d": "Manutenção de jejum por 48 horas.", "e": "Uso de benzodiazepínicos."}, "answer": "b", "rationale": "As diretrizes internacionais sugerem que a profilaxia multimodal é superior para reduzir a chance de vômitos que atrasam a alta e causam desconforto.", "option_rationales": {"a": "Incorreta. Isolada tem menor eficácia que associada.", "b": "Correta. Melhor prática clínica atual.", "c": "Incorreta.", "d": "Incorreta. Piora o quadro metabólico.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "NVPO", "Manejo"]}', 234, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente asmático, no pós-operatório de cirurgia ortopédica, recebe um anti-inflamatório não esteroidal (AINE). Minutos depois, apresenta broncoespasmo severo e vermelhidão facial. Qual o mecanismo desta reação?", "options": {"a": "Alergia mediada por IgE direta ao AINE.", "b": "Inibição da COX-1 levando ao desvio do metabolismo do ácido araquidônico para a via das lipoxigenases, aumentando a produção de leucotrienos broncoconstritores (Aspirin-Exacerbated Respiratory Disease).", "c": "Intoxicação narcótica.", "d": "Pneumonia bacteriana súbita.", "e": "Hipotensão reflexa."}, "answer": "b", "rationale": "Esta reação não é uma alergia clássica, mas sim um desequilíbrio metabólico específico em asmáticos sensíveis aos AINEs.", "option_rationales": {"a": "Incorreta. É raramente mediada por IgE.", "b": "Correta. Explicação bioquímica da tríade de Samter/asma por AINE.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Clínica Médica", "Pós-operatório", "Asma", "AINE"]}', 235, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma parotidectomia profunda, o paciente apresenta sudorese e vermelhidão em região da bochecha sempre que começa a comer. Qual o nome desta síndrome?", "options": {"a": "Sindrome de Horner.", "b": "Sindrome de Frey (Síndrome do Nervo Auriculotemporal).", "c": "Sindrome de Sjogren.", "d": "Sindrome de Mikulicz.", "e": "Tique doloroso do trigêmeo."}, "answer": "b", "rationale": "A síndrome de Frey ocorre por regeneração anômala de fibras parassimpáticas (salivares) que se conectam a receptores de suor na pele após lesão do nervo auriculotemporal.", "option_rationales": {"a": "Incorreta. Ptose, miose e enoftalmia.", "b": "Correta. Complicação neurológica autonômica tardia da parotidectomia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Parótida", "Sindrome de Frey"]}', 236, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa de ''hemoperitônio'' tardio (após 5-7 dias da cirurgia), manifestando-se por dor abdominal súbita e choque hemorrágico inexplicado após uma gastrectomia distal por câncer?", "options": {"a": "Ruptura de pseudocisto pancreático.", "b": "Sangramento do leito cirúrgico estabilizado.", "c": "Deiscência da anastomose gastro-jejunal.", "d": "Lesão iatrogênica da artéria esplênica não vista.", "e": "Erosão de um vaso arterial por uma fístula pancreática ou entérica adjacente (Pseudoaneurisma)."}, "answer": "e", "rationale": "Fístulas liberam enzimas digestivas que podem erodir paredes vasculares, criando pseudoaneurismas que rompem tardiamente.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Correta. Fisiopatologia da hemorragia sentinela após cirurgias complexas."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Hemorragia Tardia", "Pseudoaneurisma"]}', 237, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 80 anos submetido a ressecção de tumor de cólon apresenta, no 4º DPO, confusão mental, inversão do ciclo sono-vigília e desorientação. Ele não possui déficit motor. Qual a orientação prioritária para a família e enfermagem no manejo deste Delirium?", "options": {"a": "Sedação profunda com Midazolam.", "b": "Amarrar o paciente ao leito para evitar queda imediatamente.", "c": "Manter luz natural durante o dia, incentivar a presença de familiares e reorientar o paciente frequentemente.", "d": "Transferir para o isolamento.", "e": "Não realizar exames laboratoriais."}, "answer": "c", "rationale": "Medidas não farmacológicas e ambientais são as mais eficazes na prevenção e tratamento do delirium no idoso.", "option_rationales": {"a": "Incorreta. Benzodiazepínicos pioram o delirium no idoso.", "b": "Incorreta. A contenção física aumenta o estresse e risco de lesão.", "c": "Correta. Manejo não farmacológico recomendado.", "d": "Incorreta.", "e": "Incorreta. Deve-se investigar infecções/eletrólitos."}, "difficulty": "facil", "tags": ["Geriátria", "Pós-operatório", "Delirium", "Manejo"]}', 238, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''obstrução mecânica do delgado'' após cirurgias abdominais não-complicadas de longo prazo (anos depois) são:", "options": {"a": "Brida ou Aderências.", "b": "Hérnia interna.", "c": "Bezoar alimentar.", "d": "Recidiva de tumor.", "e": "Vólvulo de ceco."}, "answer": "a", "rationale": "Aderências são a causa número 1 de obstrução intestinal em pacientes que já realizaram cirurgias abdominais previas (especialmente laparotomias).", "option_rationales": {"a": "Correta. Epidemiologia cirúrgica clássica.", "b": "Incorreta.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Obstrução Intestinal", "Brida"]}', 239, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia urológica prolongada em posição de Trendelenburg (cabeça para baixo) desenvolve no pós-operatório importante edema facial e de conjuntivas (quemose). Qual o principal cuidado respiratório nesse paciente ao fim da cirurgia?", "options": {"a": "Extubação imediata assim que acordar.", "b": "Teste de vazamento de ar ao redor do balonete do tubo (Cuff Leak Test) para avaliar edema de glote antes de desentubar.", "c": "Nebulização com água destilada.", "d": "Uso de apenas ventilação não invasiva.", "e": "Fazer traqueostomia eletiva."}, "answer": "b", "rationale": "O edema facial sugere que pode haver edema de via aérea superior. O teste de vazamento ajuda a decidir se a extubação é segura ou se deve ser adiada.", "option_rationales": {"a": "Incorreta. Risco de asfixia pós-extubação por edema de glote.", "b": "Correta. Protocolo de segurança em cirurgias com edema cefálico.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Edema de Glote", "Segurança"]}', 240, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A complicação de ferida operatória conhecida como ''Deiscência Aponeurótica'' ocorre mais comumente entre qual período pós-operatório?", "options": {"a": "Primeiras 24 horas.", "b": "Entre o 5º e o 10º dia pós-operatório.", "c": "Após 30 dias.", "d": "Durante a indução anestésica.", "e": "No 2º ano."}, "answer": "b", "rationale": "É o período em que a força de tensão da ferida é mínima (fase de lag da cicatrização) e os pontos podem cortar tecidos friáveis se houver distensão ou esforço.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Período crítico de fragilidade da sutura fascial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Fisiopatologia"]}', 241, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de ''icterícia obstrutiva'' (Bilirrubina Direta elevada) após colecistectomia eletiva, sem sinais de deiscência biliar, é:", "options": {"a": "Hepatite viral.", "b": "Cálculo residual no colédoco que passou despercebido na cirurgia.", "c": "Infarto esplênico.", "d": "Dumping.", "e": "Alergia ao látex."}, "answer": "b", "rationale": "A coledocolitíase residual é uma complicação clássica, podendo manifestar-se por icterícia e dor no pós-operatório imediato ou tardio.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Principal causa de reiteração diagnóstica pós-colecistectomia.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Icterícia", "Coledocolitíase"]}', 242, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a transplante de medula óssea desenvolve no pós-operatório erupção cutânea difusa, diarreia aquosa e alteração de enzimas hepáticas. Qual a principal suspeita diagnóstica?", "options": {"a": "Infecção por HIV.", "b": "Doença do Enxerto contra o Hospedeiro (GVHD) aguda.", "c": "Rejeição hiperaguda de órgão sólido.", "d": "Sindrome de Loeffler.", "e": "Toxicidade por paracetamol."}, "answer": "b", "rationale": "A GVHD aguda ataca tipicamente pele, fígado e trato gastrointestinal, ocorrendo após transplantes de medula ou transfusões em imunodeprimidos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação imunológica específica do transplante de medula.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Hematologia", "Pós-operatório", "GVHD", "Transplante"]}', 243, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A conduta padrão para um paciente que desenvolve ''seroma calcificado'' persistente após uma mastectomia é:", "options": {"a": "Antibioticoterapia por 6 meses.", "b": "Punção aspirativa de alívio se houver dor ou desconforto estético; se crônico, pode exigir ressecção da cápsula (pseudobursa).", "c": "Drenagem imediata no centro cirúrgico apenas se estiver calcificado.", "d": "Quimioterapia intralesional.", "e": "Uso de gelo local eterno."}, "answer": "b", "rationale": "Seromas crônicos podem formar uma cápsula (bursa) que impede a reabsorção, exigindo intervenções pontuais.", "option_rationales": {"a": "Incorreta. Seroma não é infecção primária.", "b": "Correta. Manejo de complicações de feridas crônicas.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Mastologia", "Pós-operatório", "Seroma", "Manejo"]}', 244, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal complicação do uso prolongado de cateter urinário (Sonda de Foley) em pacientes do sexo masculino além da infecção urinária?", "options": {"a": "Câncer de próstata.", "b": "Estenose de uretra reacional ao trauma crônico.", "c": "Hipertensão arterial.", "d": "Fratura de bacia.", "e": "Perda de visão."}, "answer": "b", "rationale": "A inflamação crônica e a pressão do cateter sobre a mucosa uretral podem levar a fibrose e estenose uretral tardia.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação anatômica tardia urológica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Urologia", "Pós-operatório", "Sonda", "Estenose"]}', 245, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia de grande porte, observa-se que o paciente apresenta oligúria (débito < 0,5 ml/kg/h) e o sódio urinário está BAIXO (< 20 mEq/L). Qual a interpretação fisiopatológica?", "options": {"a": "Lesão renal intrínseca (NTA) estabelecida.", "b": "Estado de pré-renal (Hipovolemia) onde o rim está tentando reabsorver o máximo de sódio e água.", "c": "Obstrução pós-renal bilateral.", "d": "Intoxicação por contraste.", "e": "Uso de diuréticos."}, "answer": "b", "rationale": "A redução do Na urinário indica que a função tubular renal está preservada, reagindo adequadamente à baixa perfusão sistêmica.", "option_rationales": {"a": "Incorreta. Na NTA o sódio urinário costuma estar alto (> 40).", "b": "Correta. Diferencial bioquímico de IRA pré-renal vs renal.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Nefrologia", "Pós-operatório", "IRA", "Diagnóstico"]}', 246, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal desenvolve quadro de colite com diarreia profusa, dor abdominal e febre após o uso de antibióticos por 7 dias. O teste de toxina nas fezes é positivo para Clostridioides difficile. Qual o tratamento de primeira linha recomendado?", "options": {"a": "Loperamida (Imodium).", "b": "Vancomicina oral ou Fidaxomicina.", "c": "Amoxicilina.", "d": "Ciprofloxacino.", "e": "Dieta rica em fibras apenas."}, "answer": "b", "rationale": "A colite pseudomembranosa por C. difficile é uma complicação do uso de antibióticos. O tratamento exige antibióticos específicos que ajam no lúmen intestinal (Vancomicina oral).", "option_rationales": {"a": "Incorreta.", "b": "Correta. Tratamento atualizado para C. diff.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Infectologia", "Pós-operatório", "C. diff", "Tratamento"]}', 247, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A tríade diagnóstica da ''Rabdomiólise'' no pós-operatório (por exemplo, após cirurgias prolongadas ou compressão de membros) é composta por:", "options": {"a": "Febre, tosse e dor.", "b": "Mialgia, fraqueza muscular e urina escura (cor de chá/coca-cola).", "c": "Icterícia, vômitos e prurido.", "d": "Cefaleia, convulsão e coma.", "e": "Polidipsia, poliúria e polifagia."}, "answer": "b", "rationale": "A quebra de fibras musculares libera mioglobina na urina, conferindo-lhe a coloração escura característica.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Quadro clínico clássico de rabdomiólise.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Clínica Médica", "Pós-operatório", "Rabdomiólise", "Sinais"]}', 248, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal vantagem da cirurgia laparoscópica em relação à laparotomia aberta no que diz respeito às complicações post-operatórias precoces?", "options": {"a": "Redução da incidência de íleo paralítico e pneumonia devido à menor resposta inflamatória e deambulação mais precoce.", "b": "Menor risco de lesão iatrogênica de via biliar.", "c": "Uso de menor quantidade de gás.", "d": "Ausência completa de risco de hérnia incisional (port-site hernia).", "e": "Não exige anestesia geral."}, "answer": "a", "rationale": "O menor trauma tecidual da laparoscopia resulta em recuperação mais rápida do peristaltismo e menor dor, favorecendo a fisioterapia respiratória.", "option_rationales": {"a": "Correta. Benefícios sistêmicos da cirurgia minimamente invasiva.", "b": "Incorreta. O risco de lesão biliar é discretamente maior ou igual na laparoscopia dependendo da experiência.", "c": "Incorreta.", "d": "Incorreta. Pode ocorrer hérnia nos portais (port-site).", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Laparoscopia", "Benefícios"]}', 249, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma cirurgia biliar, o dreno apresenta saída de 500 ml de bile por dia. O paciente está muito bem, mas com icterícia. Se o dreno parasse de sair bile de repente e o paciente piorasse a dor, o cirurgião deveria suspeitar de:", "options": {"a": "Cura súbita.", "b": "Obstrução do dreno levando a bilioperitônio por acúmulo interno.", "c": "Flebite facial.", "d": "Abscesso nos pulmões.", "e": "Hérnia de hiato."}, "answer": "b", "rationale": "Se um dreno de alto débito para de funcionar sem que a fístula tenha fechado, o líquido acumulará na cavidade, causando dor e peritonite química.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Monitorização de drenos é crucial.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Drenagem", "Manejo"]}', 250, 'draft')
